{
  "name": "builder_all_pairs_gap_linear_instance_scaled_010",
  "intuition": "All pairs with linear gap weighting scaled by instance object range and log-prob std for nuanced per-instance pair weighting",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "gap_linear"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "instance_obj_range",
      "instance_log_prob_std"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = b_idx.numel()\n    if pair_count == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    eps = 1e-6\n    instance_obj_range = feature_cache['instance_obj_range']\n    instance_log_prob_std = feature_cache['instance_log_prob_std']\n    range_scale = instance_obj_range[b_idx].clamp_min(eps)\n    log_prob_scale = instance_log_prob_std[b_idx].clamp_min(eps)\n    raw_score = gap / range_scale\n    weight = raw_score / log_prob_scale\n    weight = torch.nan_to_num(weight, nan=0.0, posinf=0.0, neginf=0.0)\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = weight.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n"
}

