{
  "name": "reweight_margin_regret_instance_cond_simple",
  "intuition": "Simplify weighting by using the pairwise margin scaled inversely with instance regret_std of the winner, emphasizing stable instances; keeps margin_regret_blend semantics but avoids pairwise indexing errors.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "margin_regret_blend",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "margin_regret_blend"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "instance_regret_std"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    instance_regret_std = feature_cache['instance_regret_std']\n    # Build all pairs mask where winner's objective > loser's\n    mask = objective[:, :, None] > objective[:, None, :]\n    b_idx, win_idx, lose_idx = mask.nonzero(as_tuple=True)\n    # Pair margin: objective difference (winner - loser)\n    margin = (objective[b_idx, win_idx] - objective[b_idx, lose_idx]).clamp_min(0.0)\n    # Instance regret std of winners for scaling\n    inst_regret = instance_regret_std[b_idx, win_idx].clamp_min(1e-6)\n    # Hyperparameters controlling scaling (default values)\n    c_scale = float(extra.get('c_scale', 1.0))\n    c_shift = float(extra.get('c_shift', 0.0))\n    # Weight: margin scaled inversely with winner's instance regret std\n    weight = (margin / inst_regret) * c_scale + c_shift\n    # Clamp weights to [0,1]\n    weight = weight.clamp(0.0, 1.0)\n    return PrefBatch(\n        mode='pairwise',\n        pair_idx=(b_idx, win_idx, lose_idx),\n        weight=weight,\n        meta={'builder': 'reweight_margin_regret_instance_cond_simple'}\n    )"
}
