  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = b_idx.size(0)\n    if pair_count == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})\n    eps = 1e-6\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    obj_range = feature_cache['instance_obj_range'][b_idx].clamp_min(eps)\n    log_prob_range = feature_cache['instance_log_prob_range'][b_idx].clamp_min(eps)\n    gap_scaled = gap / obj_range\n    center = float(extra.get('bandpass_center', 1.0))\n    width = float(extra.get('bandpass_width', 0.5))\n    d = (gap_scaled - center).abs()\n    bandpass_weight = (1.0 - d / width).clamp_min(0.0)\n    modulator = torch.exp(-log_prob_range)\n    raw_weight = bandpass_weight * modulator\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = raw_weight.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})\n"
}

