{
  "name": "all_pairs_gap_bandpass_simple",
  "intuition": "Reweight all pairs with a simplified bandpass filter on gap normalized by instance_obj_range, emphasizing medium gaps and modulating by inverse instance_log_prob_std for confidence.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
