  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    eps = 1e-6\n    instance_obj_range = feature_cache['instance_obj_range']\n    instance_log_prob_std = feature_cache['instance_log_prob_std']\n    gap_scaled = gap / instance_obj_range[b_idx].clamp_min(eps)\n    low_cut = float(extra.get('low_cut', 0.2))\n    high_cut = float(extra.get('high_cut', 1.2))\n    rise = (gap_scaled - low_cut) / (high_cut - low_cut)\n    fall = (high_cut - gap_scaled) / (high_cut - low_cut)\n    rise = rise.clamp(0.0, 1.0)\n    fall = fall.clamp(0.0, 1.0)\n    raw_weight = rise * fall\n    inv_log_prob_std = 1.0 / instance_log_prob_std[b_idx].clamp_min(eps)\n    raw_weight = raw_weight * inv_log_prob_std\n    raw_weight = raw_weight.clamp(min=0.0)\n    weight = raw_weight.clamp(min=0.25, max=4.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})\n"
}

